-- Reviewed senior batch 027; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":5411,"word":"abnormal","meaning":"異常的","example":"The engineer investigated an abnormal vibration in the machine.","example_zh":"工程師調查機器的異常振動。","original_meaning":"異常的","original_example":"Abnormal behavior.","original_example_zh":"異常行為。"},{"source_id":5413,"word":"acquaint","meaning":"使認識","example":"The tour will acquaint students with the town's history.","example_zh":"導覽將讓學生認識這座小鎮的歷史。","original_meaning":"使認識","original_example":"Acquaint with the rules.","original_example_zh":"熟悉規則。"},{"source_id":5414,"word":"activate","meaning":"啟動","example":"Pressing the button will activate the display.","example_zh":"按下按鈕就會啟動展示裝置。","original_meaning":"啟動","original_example":"Activate the alarm.","original_example_zh":"啟動警報。"},{"source_id":5415,"word":"addict","meaning":"上癮者","example":"The novel follows a recovering addict who rebuilds his friendships.","example_zh":"小說描寫一位正在戒癮的人如何重建友誼。","original_meaning":"上癮者","original_example":"A social media addict.","original_example_zh":"一位社群媒體成癮者。"},{"source_id":5419,"word":"alarming","meaning":"令人擔憂的","example":"The alarming crack led the engineer to close the bridge.","example_zh":"這道令人擔憂的裂縫使工程師封閉橋梁。","original_meaning":"令人擔憂的","original_example":"An alarming trend.","original_example_zh":"令人擔憂的趨勢。"},{"source_id":5421,"word":"antenna","meaning":"天線","example":"The technician adjusted the antenna on the roof.","example_zh":"技術人員調整屋頂上的天線。","original_meaning":"天線","original_example":"A radio antenna.","original_example_zh":"無線電天線。"},{"source_id":5422,"word":"applicable","meaning":"適用的","example":"The same rule is applicable to both activities.","example_zh":"同一規則適用於這兩項活動。","original_meaning":"適用的","original_example":"Rules applicable to all.","original_example_zh":"適用於所有人的規則。"},{"source_id":5423,"word":"assault","meaning":"攻擊","example":"The history class discussed the assault on the old fort.","example_zh":"歷史課討論了對古堡的攻擊。","original_meaning":"攻擊","original_example":"An assault charge.","original_example_zh":"一項襲擊指控。"},{"source_id":5427,"word":"bankrupt","meaning":"破產的","example":"The bankrupt company sold its remaining equipment.","example_zh":"破產公司出售剩餘設備。","original_meaning":"破產的","original_example":"Go bankrupt.","original_example_zh":"宣告破產。"},{"source_id":5429,"word":"bracket","meaning":"括號","example":"She placed a bracket around the extra information.","example_zh":"她用括號括住補充資訊。","original_meaning":"括號","original_example":"Put in brackets.","original_example_zh":"加上括號。"},{"source_id":5430,"word":"bypass","meaning":"繞過","example":"The walkers used a side path to bypass the muddy section.","example_zh":"步行者走旁邊小徑，繞過泥濘路段。","original_meaning":"繞過","original_example":"Bypass the blockade.","original_example_zh":"繞過封鎖線。"},{"source_id":5433,"word":"compute","meaning":"計算","example":"The students used a spreadsheet to compute the total.","example_zh":"學生用試算表計算總數。","original_meaning":"計算","original_example":"Compute the total.","original_example_zh":"計算總和。"},{"source_id":5439,"word":"fuse","meaning":"保險絲","example":"The electrician examined the fuse after disconnecting the power.","example_zh":"電工斷電後檢查保險絲。","original_meaning":"保險絲","original_example":"Replace the fuse.","original_example_zh":"更換保險絲。"},{"source_id":5441,"word":"hospitable","meaning":"好客的","example":"The hospitable family welcomed the travelers with tea.","example_zh":"好客的家庭用茶款待旅人。","original_meaning":"好客的","original_example":"A hospitable family.","original_example_zh":"一個好客的家庭。"},{"source_id":5452,"word":"bachelor","meaning":"單身漢","example":"The bachelor invited his friends to his new apartment.","example_zh":"這位單身漢邀朋友到新公寓作客。","original_meaning":"單身漢","original_example":"A bachelor degree.","original_example_zh":"學士學位。"},{"source_id":5454,"word":"bolt","meaning":"螺栓","example":"The mechanic tightened the bolt on the frame.","example_zh":"機械師鎖緊框架上的螺栓。","original_meaning":"螺栓","original_example":"A bolt of lightning.","original_example_zh":"一道閃電。"},{"source_id":5458,"word":"choir","meaning":"合唱團","example":"The choir rehearsed in the school hall.","example_zh":"合唱團在學校禮堂排練。","original_meaning":"合唱團","original_example":"Join the choir.","original_example_zh":"加入合唱團。"},{"source_id":5464,"word":"junction","meaning":"交叉口","example":"The bus stopped near the junction of two main roads.","example_zh":"公車停在兩條主要道路的交叉口附近。","original_meaning":"交叉口","original_example":"A road junction.","original_example_zh":"一個道路交叉口。"},{"source_id":5467,"word":"kneel","meaning":"跪","example":"The gardener had to kneel to plant the small flowers.","example_zh":"園丁必須跪下來種小花。","original_meaning":"跪","original_example":"Kneel down.","original_example_zh":"跪下。"},{"source_id":5468,"word":"layout","meaning":"佈局","example":"The architect changed the layout to create more open space.","example_zh":"建築師更改佈局，騰出更多開放空間。","original_meaning":"佈局","original_example":"The page layout.","original_example_zh":"版面配置。"},{"source_id":5471,"word":"limb","meaning":"肢體","example":"The students examined a model of a human limb.","example_zh":"學生觀察人體肢體的模型。","original_meaning":"肢體","original_example":"An artificial limb.","original_example_zh":"義肢。"},{"source_id":5474,"word":"lone","meaning":"單獨的；孤零零的","example":"A lone tree stood in the middle of the field.","example_zh":"田野中央矗立著一棵孤零零的樹。","original_meaning":"孤獨的","original_example":"A lone wolf.","original_example_zh":"獨行俠。"},{"source_id":5475,"word":"loop","meaning":"環；循環","example":"The forest trail formed a loop around the lake.","example_zh":"森林步道繞湖形成環線。","original_meaning":"循環","original_example":"A feedback loop.","original_example_zh":"反饋迴路。"},{"source_id":5479,"word":"majority","meaning":"大多數","example":"The majority of the class chose the river cleanup project.","example_zh":"班上大多數人選擇河川清理計畫。","original_meaning":"大多數","original_example":"The majority of students preferred a later start for Saturday practice.","original_example_zh":"大多數學生希望星期六練習晚一點開始。"},{"source_id":5481,"word":"mansion","meaning":"豪宅","example":"The old mansion became a public museum.","example_zh":"這座老豪宅成為公共博物館。","original_meaning":"豪宅","original_example":"A grand mansion.","original_example_zh":"一棟宏偉的宅邸。"},{"source_id":5482,"word":"martial","meaning":"軍事的","example":"The museum examined martial traditions in the ancient kingdom.","example_zh":"博物館探討古代王國的軍事傳統。","original_meaning":"軍事的","original_example":"Martial arts.","original_example_zh":"武術。"},{"source_id":5483,"word":"meadow","meaning":"草地","example":"Wildflowers covered the sunny meadow.","example_zh":"野花覆滿陽光照耀的草地。","original_meaning":"草地","original_example":"A green meadow.","original_example_zh":"一片綠草如茵的草地。"},{"source_id":5484,"word":"multimedia","meaning":"多媒體","example":"The exhibition used multimedia to tell the harbor's story.","example_zh":"展覽利用多媒體講述港口故事。","original_meaning":"多媒體","original_example":"A multimedia presentation.","original_example_zh":"多媒體簡報。"},{"source_id":5485,"word":"municipal","meaning":"市政的","example":"The municipal library opened a new reading room.","example_zh":"市立圖書館開設了新閱覽室。","original_meaning":"市政的","original_example":"Municipal government.","original_example_zh":"市政府。"},{"source_id":5486,"word":"oak","meaning":"橡樹","example":"An old oak shaded the village square.","example_zh":"一棵老橡樹為村莊廣場遮蔭。","original_meaning":"橡樹","original_example":"An oak tree.","original_example_zh":"一棵橡樹。"},{"source_id":5487,"word":"oppress","meaning":"壓迫","example":"The novel showed how unfair laws could oppress a community.","example_zh":"小說呈現不公法律如何壓迫一個社群。","original_meaning":"壓迫","original_example":"Oppress minorities.","original_example_zh":"壓迫少數族群。"},{"source_id":5488,"word":"overtake","meaning":"超越","example":"The runner managed to overtake the leader near the finish.","example_zh":"跑者在接近終點時成功超越領先者。","original_meaning":"超越","original_example":"Overtake the leader.","original_example_zh":"超越領先者。"},{"source_id":5489,"word":"pacific","meaning":"和平的；愛好和平的","example":"The mediator took a pacific approach to settling the dispute.","example_zh":"調解人以和平方式處理爭端。","original_meaning":"太平洋的","original_example":"The Pacific Ocean.","original_example_zh":"太平洋。"},{"source_id":5490,"word":"patrol","meaning":"巡邏","example":"The park patrol checked the trail before sunrise.","example_zh":"公園巡邏隊在日出前檢查步道。","original_meaning":"巡邏","original_example":"A police patrol.","original_example_zh":"警察巡邏。"},{"source_id":5492,"word":"preside","meaning":"主持","example":"The teacher invited a student to preside over the discussion.","example_zh":"老師邀請一位學生主持討論。","original_meaning":"主持","original_example":"Preside over a meeting.","original_example_zh":"主持會議。"},{"source_id":5493,"word":"prevail","meaning":"盛行","example":"Cooperation began to prevail over rivalry in the group.","example_zh":"小組裡合作逐漸勝過競爭。","original_meaning":"盛行","original_example":"Justice prevailed.","original_example_zh":"正義得以伸張。"},{"source_id":5494,"word":"pump","meaning":"幫浦","example":"The pump moved water from the tank to the garden.","example_zh":"幫浦把水從水槽送往花園。","original_meaning":"幫浦","original_example":"A water pump.","original_example_zh":"水泵。"},{"source_id":5496,"word":"rebel","meaning":"反叛者","example":"The story's rebel challenged the ruler's unfair demands.","example_zh":"故事中的反叛者挑戰統治者不公的要求。","original_meaning":"反叛者","original_example":"A rebel group.","original_example_zh":"一個反抗組織。"},{"source_id":5497,"word":"rigid","meaning":"僵硬的","example":"The rigid frame kept the model from bending.","example_zh":"堅硬框架使模型不易彎曲。","original_meaning":"僵硬的","original_example":"A rigid schedule.","original_example_zh":"緊湊的行程。"},{"source_id":5498,"word":"scatter","meaning":"散開","example":"A sudden breeze began to scatter the dry leaves.","example_zh":"一陣微風開始吹散乾葉。","original_meaning":"散開","original_example":"Scatter the seeds.","original_example_zh":"撒播種子。"},{"source_id":5499,"word":"serial","meaning":"連續的；連載的","example":"The writer published her story in serial form.","example_zh":"作家以連載形式發表故事。","original_meaning":"連續的","original_example":"A serial number.","original_example_zh":"序號。"},{"source_id":5500,"word":"shuttle","meaning":"接駁車","example":"The shuttle carried visitors from the station to the museum.","example_zh":"接駁車載訪客從車站前往博物館。","original_meaning":"接駁車","original_example":"A space shuttle.","original_example_zh":"太空梭。"},{"source_id":5503,"word":"spacecraft","meaning":"太空船","example":"The spacecraft sent images of the planet back to Earth.","example_zh":"太空船把行星影像傳回地球。","original_meaning":"太空船","original_example":"A manned spacecraft.","original_example_zh":"載人太空船。"},{"source_id":5504,"word":"stake","meaning":"利害關係","example":"The residents had a stake in the park's future.","example_zh":"居民與公園的未來有利害關係。","original_meaning":"利害關係","original_example":"At stake.","original_example_zh":"岌岌可危。"},{"source_id":5505,"word":"stale","meaning":"不新鮮的","example":"The bread tasted stale after several days.","example_zh":"麵包放了幾天後吃起來不新鮮。","original_meaning":"不新鮮的","original_example":"Stale bread.","original_example_zh":"發霉的麵包。"},{"source_id":5506,"word":"stance","meaning":"立場","example":"The mayor explained her stance on the proposed bridge.","example_zh":"市長說明她對擬建橋梁的立場。","original_meaning":"立場","original_example":"A political stance.","original_example_zh":"政治立場。"},{"source_id":5507,"word":"statistical","meaning":"統計的","example":"The team used statistical methods to compare the results.","example_zh":"團隊用統計方法比較結果。","original_meaning":"統計的","original_example":"Statistical analysis.","original_example_zh":"統計分析。"},{"source_id":5508,"word":"suite","meaning":"套房","example":"The family stayed in a suite with a small living room.","example_zh":"這家人住在一間附小客廳的套房。","original_meaning":"套房","original_example":"A hotel suite.","original_example_zh":"一間酒店套房。"},{"source_id":5510,"word":"taxpayer","meaning":"納稅人","example":"Each taxpayer received information about the new system.","example_zh":"每位納稅人都收到新制度的資訊。","original_meaning":"納稅人","original_example":"A responsible taxpayer.","original_example_zh":"負責任的納稅人。"},{"source_id":5512,"word":"terrorism","meaning":"恐怖主義","example":"The class discussed the effects of terrorism on ordinary communities.","example_zh":"全班討論恐怖主義對一般社區的影響。","original_meaning":"恐怖主義","original_example":"Fight terrorism.","original_example_zh":"打擊恐怖主義。"},{"source_id":5513,"word":"utilize","meaning":"利用","example":"The school will utilize the empty room as an art studio.","example_zh":"學校將利用空教室作為美術工作室。","original_meaning":"利用","original_example":"Utilize resources.","original_example_zh":"善用資源。"},{"source_id":5516,"word":"worship","meaning":"崇拜","example":"People gather at the temple to worship.","example_zh":"人們聚集在寺廟禮拜。","original_meaning":"崇拜","original_example":"Worship at a temple.","original_example_zh":"在寺廟裡參拜。"},{"source_id":5517,"word":"awe","meaning":"敬畏","example":"The students watched the waterfall in awe.","example_zh":"學生敬畏地望著瀑布。","original_meaning":"敬畏","original_example":"Stand in awe.","original_example_zh":"感到敬畏。"},{"source_id":5520,"word":"gloom","meaning":"陰鬱","example":"Dark clouds filled the valley with gloom.","example_zh":"烏雲使山谷籠罩在陰鬱氣氛中。","original_meaning":"陰鬱","original_example":"A sense of gloom.","original_example_zh":"一種陰鬱的感覺。"},{"source_id":5522,"word":"morale","meaning":"士氣","example":"The captain's kind words raised the team's morale.","example_zh":"隊長溫暖的話語提升了團隊士氣。","original_meaning":"士氣","original_example":"Boost morale.","original_example_zh":"提振士氣。"},{"source_id":5523,"word":"remorse","meaning":"懊悔","example":"He felt remorse after breaking his promise.","example_zh":"他違背承諾後感到懊悔。","original_meaning":"懊悔","original_example":"Feel remorse.","original_example_zh":"感到懊悔。"},{"source_id":5524,"word":"sorrow","meaning":"悲傷","example":"Her friends shared her sorrow after her grandmother died.","example_zh":"祖母過世後，朋友陪伴她分擔悲傷。","original_meaning":"悲傷","original_example":"Deep sorrow.","original_example_zh":"深切的悲痛。"},{"source_id":5526,"word":"dew","meaning":"露水","example":"Drops of dew sparkled on the grass.","example_zh":"露珠在草葉上閃閃發亮。","original_meaning":"露水","original_example":"Morning dew.","original_example_zh":"晨露。"},{"source_id":5528,"word":"sensor","meaning":"感測器","example":"The sensor turned on the light when someone entered.","example_zh":"有人進門時，感測器就打開燈。","original_meaning":"感測器","original_example":"A motion sensor.","original_example_zh":"動作感測器。"},{"source_id":5529,"word":"server","meaning":"伺服器","example":"The technician checked the server in the computer room.","example_zh":"技術人員檢查電腦機房的伺服器。","original_meaning":"伺服器","original_example":"A web server.","original_example_zh":"網路伺服器。"},{"source_id":5532,"word":"canvas","meaning":"畫布","example":"The artist stretched a fresh canvas over the frame.","example_zh":"畫家把新畫布繃在框上。","original_meaning":"畫布","original_example":"Paint on canvas.","original_example_zh":"在畫布上作畫。"},{"source_id":5533,"word":"chorus","meaning":"合唱","example":"The chorus filled the hall with a rich sound.","example_zh":"合唱聲充滿禮堂，十分飽滿。","original_meaning":"合唱","original_example":"A song chorus.","original_example_zh":"歌曲副歌。"},{"source_id":5534,"word":"composer","meaning":"作曲家","example":"The composer tested a new melody at the piano.","example_zh":"作曲家在鋼琴上試奏新旋律。","original_meaning":"作曲家","original_example":"A famous composer.","original_example_zh":"一位著名的作曲家。"},{"source_id":5536,"word":"seasoning","meaning":"調味料；調味","example":"The cook tasted the soup before adding more seasoning.","example_zh":"廚師先嚐湯，再加更多調味料。","original_meaning":"調味料；調味","original_example":"I tasted the soup before adding more seasoning.","original_example_zh":"我先嘗了湯的味道，才決定是否再加調味料。"},{"source_id":5537,"word":"invoice","meaning":"發票","example":"The supplier sent an invoice with the delivery.","example_zh":"供應商隨貨寄來發票。","original_meaning":"發票","original_example":"Send an invoice.","original_example_zh":"寄送發票。"},{"source_id":5538,"word":"lease","meaning":"租約","example":"They signed a lease for the small shop.","example_zh":"他們簽下小店面的租約。","original_meaning":"租約","original_example":"Sign a lease.","original_example_zh":"簽訂租約。"},{"source_id":5539,"word":"tuition","meaning":"學費","example":"She saved money to help pay her college tuition.","example_zh":"她存錢以協助支付大學學費。","original_meaning":"學費","original_example":"High tuition fees.","original_example_zh":"高昂的學費。"},{"source_id":5540,"word":"cabinet","meaning":"內閣","example":"The cabinet met to discuss the national budget.","example_zh":"內閣開會討論國家預算。","original_meaning":"內閣","original_example":"The cabinet meeting.","original_example_zh":"內閣會議。"},{"source_id":5542,"word":"democrat","meaning":"民主主義者","example":"The democrat argued that citizens should have a voice in government.","example_zh":"這位民主主義者主張人民應有參與政府的發言權。","original_meaning":"民主黨人","original_example":"A lifelong democrat.","original_example_zh":"終身民主派。"},{"source_id":5543,"word":"devastating","meaning":"毀滅性的","example":"The exhibit described the devastating effects of the storm.","example_zh":"展覽描述風暴帶來的毀滅性影響。","original_meaning":"毀滅性的","original_example":"A devastating loss.","original_example_zh":"一場毀滅性的損失。"},{"source_id":5544,"word":"facade","meaning":"建築正面；外觀","example":"Workers carefully restored the theater's stone facade.","example_zh":"工人仔細修復劇院的石造正面。","original_meaning":"外觀","original_example":"Behind the facade.","original_example_zh":"表象背後。"},{"source_id":6345,"word":"routine","meaning":"例行習慣；日常作息","example":"Her morning routine began with feeding the cat.","example_zh":"她的早晨日常從餵貓開始。","original_meaning":"例行習慣；日常作息","original_example":"My morning routine became calmer after I packed my bag the night before.","original_example_zh":"我改成前一晚整理書包後，早晨的日常作息變得從容許多。"},{"source_id":6346,"word":"household","meaning":"家庭；家務的","example":"Every household received a recycling guide.","example_zh":"每戶家庭都收到一份回收指南。","original_meaning":"家庭；家務的","original_example":"Everyone in our household takes turns washing the dishes.","original_example_zh":"我們家每個人都輪流洗碗。"},{"source_id":6347,"word":"maintain","meaning":"維持；保養","example":"The volunteers help maintain the community garden.","example_zh":"志工協助維護社區花園。","original_meaning":"維持；保養","original_example":"Regular walks help Grandpa maintain his strength without hurting his knees.","original_example_zh":"固定散步幫助爺爺維持體力，又不會傷到膝蓋。"},{"source_id":6348,"word":"recover","meaning":"恢復；康復","example":"The town worked together to recover after the flood.","example_zh":"洪水過後，全鎮同心協力恢復生活。","original_meaning":"恢復；康復","original_example":"I stayed home for two days to recover from a bad cold.","original_example_zh":"我在家休息兩天，讓自己從重感冒中康復。"},{"source_id":6349,"word":"exhausted","meaning":"精疲力盡的","example":"After the long hike, the exhausted walkers rested at the lodge.","example_zh":"長途健行後，精疲力盡的步行者在山屋休息。","original_meaning":"精疲力盡的","original_example":"After rehearsing until nine, the band members were exhausted but satisfied.","original_example_zh":"排練到九點後，樂團成員筋疲力盡，卻很有成就感。"},{"source_id":6350,"word":"stress","meaning":"壓力","example":"The students talked about stress before the exams.","example_zh":"學生在考試前談論壓力。","original_meaning":"壓力","original_example":"Taking a short walk helps me manage stress before a major exam.","original_example_zh":"大考前短暫散步能幫助我調整壓力。"},{"source_id":6351,"word":"convenient","meaning":"方便的","example":"The new bus stop made the library more convenient to reach.","example_zh":"新公車站讓前往圖書館更加方便。","original_meaning":"方便的","original_example":"The clinic is convenient because it is beside the MRT exit.","original_example_zh":"這間診所在捷運出口旁，所以很方便。"},{"source_id":6352,"word":"independent","meaning":"獨立的","example":"The independent learner planned her own study schedule.","example_zh":"這位獨立學習者自行規畫讀書時間。","original_meaning":"獨立的","original_example":"Living in the dorm taught my brother to become more independent.","original_example_zh":"住校讓哥哥學會變得更加獨立。"},{"source_id":6353,"word":"responsibility","meaning":"責任","example":"Caring for the class plants was his responsibility.","example_zh":"照顧班上的植物是他的責任。","original_meaning":"責任","original_example":"Feeding the family dog every morning is my responsibility.","original_example_zh":"每天早上餵家裡的狗是我的責任。"},{"source_id":6354,"word":"hygiene","meaning":"衛生","example":"The lesson emphasized good kitchen hygiene.","example_zh":"這堂課強調良好的廚房衛生。","original_meaning":"衛生","original_example":"Good kitchen hygiene begins with clean hands and separate cutting boards.","original_example_zh":"良好的廚房衛生從乾淨的雙手與分開使用的砧板開始。"},{"source_id":6356,"word":"appointment","meaning":"預約；約會","example":"She made an appointment to meet her teacher.","example_zh":"她預約了與老師會面的時間。","original_meaning":"預約；約會","original_example":"I moved my dental appointment because it overlapped with the debate contest.","original_example_zh":"牙醫預約和辯論比賽撞期，所以我更改了時間。"},{"source_id":6358,"word":"emergency","meaning":"緊急事件；緊急的","example":"The school practiced how to respond to an emergency.","example_zh":"學校演練如何應對緊急事件。","original_meaning":"緊急事件；緊急的","original_example":"Our family keeps flashlights and drinking water ready for an emergency.","original_example_zh":"我們家備妥手電筒和飲用水，以應付緊急狀況。"},{"source_id":6360,"word":"priority","meaning":"優先事項","example":"Repairing the bridge became the town's first priority.","example_zh":"修復橋梁成為鎮上首要任務。","original_meaning":"優先事項","original_example":"Getting enough sleep became my priority during exam week.","original_example_zh":"考試週期間，睡眠充足成了我的首要事項。"},{"source_id":6361,"word":"flexible","meaning":"有彈性的；靈活的","example":"The flexible schedule allowed time for both study and sport.","example_zh":"有彈性的時間安排兼顧了讀書與運動。","original_meaning":"有彈性的；靈活的","original_example":"My study plan is flexible enough to leave Friday evening free.","original_example_zh":"我的讀書計畫很有彈性，能把星期五晚上空下來。"},{"source_id":6362,"word":"well-being","meaning":"身心健康；福祉","example":"The new park improved the residents' sense of well-being.","example_zh":"新公園提升了居民的幸福感。","original_meaning":"身心健康；福祉","original_example":"Turning off notifications at night improved my sleep and well-being.","original_example_zh":"晚上關閉通知改善了我的睡眠與身心狀態。"},{"source_id":6363,"word":"frequency","meaning":"頻率","example":"The chart showed the frequency of library visits.","example_zh":"圖表顯示造訪圖書館的頻率。","original_meaning":"頻率","original_example":"We recorded the frequency of buses arriving after eight in the morning.","original_example_zh":"我們記錄了早上八點後公車抵達的頻率。"},{"source_id":6364,"word":"annual","meaning":"每年的；年度的","example":"The annual festival brought neighbors together.","example_zh":"年度節慶讓鄰居聚在一起。","original_meaning":"每年的；年度的","original_example":"The annual school fair raises money for the community food bank.","original_example_zh":"一年一度的校慶園遊會為社區食物銀行募款。"},{"source_id":6365,"word":"monthly","meaning":"每月的；按月","example":"The club holds a monthly meeting at the library.","example_zh":"社團每月在圖書館開一次會。","original_meaning":"每月的；按月","original_example":"I review my monthly spending before adding money to my travel fund.","original_example_zh":"我會先檢視每月支出，再把錢存進旅行基金。"},{"source_id":6369,"word":"proportion","meaning":"比例；部分","example":"A large proportion of the garden was planted with native flowers.","example_zh":"花園中很大一部分種了原生花卉。","original_meaning":"比例；部分","original_example":"A large proportion of our electricity bill comes from air conditioning.","original_example_zh":"我們家的電費有很大一部分來自冷氣。"},{"source_id":6371,"word":"estimate","meaning":"估計；估價","example":"The builder gave us an estimate for repairing the roof.","example_zh":"建築工人向我們提供屋頂修理估價。","original_meaning":"估計；估價","original_example":"We estimated the meal cost before inviting the whole basketball team.","original_example_zh":"邀請整支籃球隊前，我們先估算了餐費。"},{"source_id":6372,"word":"statistics","meaning":"統計資料","example":"The statistics showed a rise in bicycle use.","example_zh":"統計資料顯示自行車使用量增加。","original_meaning":"統計資料","original_example":"The article used traffic statistics from the city government.","original_example_zh":"這篇文章引用了市政府的交通統計資料。"},{"source_id":6373,"word":"data","meaning":"資料；數據","example":"The students collected data about rainfall.","example_zh":"學生蒐集降雨量資料。","original_meaning":"資料；數據","original_example":"Our group saved the survey data in a shared spreadsheet.","original_example_zh":"我們小組把問卷數據儲存在共用試算表中。"},{"source_id":6375,"word":"sequence","meaning":"順序；連續","example":"She arranged the pictures in the correct sequence.","example_zh":"她把圖片排成正確順序。","original_meaning":"順序；連續","original_example":"I wrote down the sequence of stops so my cousin would not get lost.","original_example_zh":"我寫下各站順序，這樣表弟就不會迷路。"},{"source_id":6376,"word":"quantity","meaning":"數量","example":"The recipe required only a small quantity of oil.","example_zh":"這份食譜只需要少量油。","original_meaning":"數量","original_example":"The recipe changes depending on the quantity of rice we cook.","original_example_zh":"食譜會依我們煮的米量而調整。"},{"source_id":6377,"word":"rate","meaning":"比率；速度；費用","example":"The students compared the rate at which two toy cars moved.","example_zh":"學生比較兩輛玩具車移動的速度。","original_meaning":"比率；速度；費用","original_example":"The hotel offered a lower rate for students attending the competition.","original_example_zh":"飯店為參加比賽的學生提供較低房價。"},{"source_id":6378,"word":"ratio","meaning":"比率；比例","example":"The model used a ratio of two blue blocks to one red block.","example_zh":"模型使用兩塊藍積木對一塊紅積木的比例。","original_meaning":"比率；比例","original_example":"We mixed paint at a ratio of two parts blue to one part white.","original_example_zh":"我們用兩份藍色配一份白色的比例調顏料。"},{"source_id":6380,"word":"population","meaning":"人口；族群數量","example":"The town's population grew after the railway opened.","example_zh":"鐵路開通後，鎮上人口增加。","original_meaning":"人口；族群數量","original_example":"The bird population near the river grew after the wetland was restored.","original_example_zh":"濕地復育後，河邊的鳥類數量增加了。"},{"source_id":6381,"word":"trend","meaning":"趨勢","example":"The survey revealed a trend toward cycling to school.","example_zh":"問卷顯示騎車上學的趨勢。","original_meaning":"趨勢","original_example":"The chart shows a trend toward fewer cash payments at convenience stores.","original_example_zh":"圖表顯示便利商店使用現金付款逐漸減少的趨勢。"},{"source_id":6382,"word":"calculation","meaning":"計算","example":"She checked the calculation before submitting the report.","example_zh":"她在提交報告前核對計算。","original_meaning":"計算","original_example":"I found an error in the calculation before we submitted the lab report.","original_example_zh":"提交實驗報告前，我發現計算中有一個錯誤。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-abnormal-01-v1","level":"senior","word":"abnormal","sort_order":1,"sense":"異常的","alt_zh":"成年工程師在安全罩外觀察機器與振動圖表，思索異常。","example":"The engineer investigated an abnormal vibration in the machine.","example_zh":"工程師調查機器的異常振動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/abnormal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-acquaint-01-v1","level":"senior","word":"acquaint","sort_order":1,"sense":"使認識","alt_zh":"成年導覽員在古城模型前向高中生講解。","example":"The tour will acquaint students with the town's history.","example_zh":"導覽將讓學生認識這座小鎮的歷史。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/acquaint-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-activate-01-v1","level":"senior","word":"activate","sort_order":1,"sense":"啟動","alt_zh":"成年訪客按科學館大型簡單按鈕，封閉展示模型亮起柔光。","example":"Pressing the button will activate the display.","example_zh":"按下按鈕就會啟動展示裝置。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/activate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-addict-01-v1","level":"senior","word":"addict","sort_order":1,"sense":"上癮者","alt_zh":"圖書館桌上小說插圖呈現穿完整日常服裝的成年男子與朋友溫暖交談，無物質或用藥。","example":"The novel follows a recovering addict who rebuilds his friendships.","example_zh":"小說描寫一位正在戒癮的人如何重建友誼。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/addict-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-alarming-01-v1","level":"senior","word":"alarming","sort_order":1,"sense":"令人擔憂的","alt_zh":"成年工程師在安全柵欄外檢視橋面裂縫，橋上無人。","example":"The alarming crack led the engineer to close the bridge.","example_zh":"這道令人擔憂的裂縫使工程師封閉橋梁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alarming-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-antenna-01-v1","level":"senior","word":"antenna","sort_order":1,"sense":"天線","alt_zh":"成年技師穿安全裝備在有護欄的平屋頂調整天線。","example":"The technician adjusted the antenna on the roof.","example_zh":"技術人員調整屋頂上的天線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/antenna-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-applicable-01-v1","level":"senior","word":"applicable","sort_order":1,"sense":"適用的","alt_zh":"成年教師在兩個相似桌上遊戲旁指出共同規則圖卡。","example":"The same rule is applicable to both activities.","example_zh":"同一規則適用於這兩項活動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/applicable-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-assault-01-v1","level":"senior","word":"assault","sort_order":1,"sense":"攻擊","alt_zh":"歷史教室桌上靜態古堡地形模型，成年教師講解，無人物戰鬥傷害。","example":"The history class discussed the assault on the old fort.","example_zh":"歷史課討論了對古堡的攻擊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/assault-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bankrupt-01-v1","level":"senior","word":"bankrupt","sort_order":1,"sense":"破產的","alt_zh":"成年公司人員在安靜倉庫清點待出售的辦公設備。","example":"The bankrupt company sold its remaining equipment.","example_zh":"破產公司出售剩餘設備。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bankrupt-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bracket-01-v1","level":"senior","word":"bracket","sort_order":1,"sense":"括號","alt_zh":"近景學生筆記本上一對大圓括號包住抽象短線文字，桌上文具。","example":"She placed a bracket around the extra information.","example_zh":"她用括號括住補充資訊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bracket-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bypass-01-v1","level":"senior","word":"bypass","sort_order":1,"sense":"繞過","alt_zh":"成年健行者沿乾燥側邊步道繞過積水泥地。","example":"The walkers used a side path to bypass the muddy section.","example_zh":"步行者走旁邊小徑，繞過泥濘路段。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bypass-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-compute-01-v1","level":"senior","word":"compute","sort_order":1,"sense":"計算","alt_zh":"學生在教室筆電上查看整齊數值方格與計算機，無可讀文字。","example":"The students used a spreadsheet to compute the total.","example_zh":"學生用試算表計算總數。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compute-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-fuse-01-v1","level":"senior","word":"fuse","sort_order":1,"sense":"保險絲","alt_zh":"成年電工在乾燥工作桌用放大鏡看已取下的小保險絲，設備插頭明確拔除。","example":"The electrician examined the fuse after disconnecting the power.","example_zh":"電工斷電後檢查保險絲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fuse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-hospitable-01-v1","level":"senior","word":"hospitable","sort_order":1,"sense":"好客的","alt_zh":"成年主人在溫暖客廳向成年旅人端茶，親切交談。","example":"The hospitable family welcomed the travelers with tea.","example_zh":"好客的家庭用茶款待旅人。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/hospitable-01-v1.webp","local_path":"","style":"g